import{_ as i,c as e,o,ae as n}from"./chunks/framework.BQlYxExx.js";const d=JSON.parse('{"title":"Sesja Event Storming / User Stories","description":"","frontmatter":{},"headers":[],"relativePath":"event-storming.md","filePath":"event-storming.md"}'),t={name:"event-storming.md"};function r(s,a,c,l,z,w){return o(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="sesja-event-storming-user-stories" tabindex="-1">Sesja Event Storming / User Stories <a class="header-anchor" href="#sesja-event-storming-user-stories" aria-label="Permalink to &quot;Sesja Event Storming / User Stories&quot;">​</a></h1><h2 id="_4-1-event-storming" tabindex="-1">4.1. Event Storming <a class="header-anchor" href="#_4-1-event-storming" aria-label="Permalink to &quot;4.1. Event Storming&quot;">​</a></h2><p>Sesja Event Storming została przeprowadzona online za pomocą narzędzia Miro, aby zidentyfikować kluczowe zdarzenia (Events), polecenia (Commands) i systemy (System boundaries) w domenie adopcji zwierząt. Sesja pomogła w walidacji założeń projektowych oraz wyznaczeniu wstępnych granic kontekstów (Bounded Contexts) dla Backendu.</p><h3 id="kluczowe-zdarzenia-events" tabindex="-1">Kluczowe Zdarzenia (Events) <a class="header-anchor" href="#kluczowe-zdarzenia-events" aria-label="Permalink to &quot;Kluczowe Zdarzenia (Events)&quot;">​</a></h3><p>Zdarzenia, które mają znaczenie dla aplikacji ŁapGo:</p><ul><li><strong>Ogłoszenie Zostało Zaggregowane</strong>: Nowe ogłoszenie zwierzęcia zostało pomyślnie pobrane i sparsowane przez scraper.</li><li><strong>Ogłoszenie Zostało Zweryfikowane</strong>: Administrator potwierdził poprawność i aktualność danych ogłoszenia.</li><li><strong>Zwierzę Zostało Dodane Do Ulubionych</strong>: Użytkownik dodał zwierzę do listy obserwowanych.</li><li><strong>Preferencje Zostały Zaktualizowane</strong>: Użytkownik zmienił kryteria wyszukiwania wymarzonego zwierzaka.</li><li><strong>Zwierzę Zostało Adoptowane</strong>: Status zwierzęcia zmienił się na &quot;Adoptowane&quot;, co wymaga usunięcia/zarchiwizowania ogłoszenia.</li></ul><h3 id="granice-kontekstow-bounded-contexts" tabindex="-1">Granice Kontekstów (Bounded Contexts) <a class="header-anchor" href="#granice-kontekstow-bounded-contexts" aria-label="Permalink to &quot;Granice Kontekstów (Bounded Contexts)&quot;">​</a></h3><p>Podczas sesji wstępnie zdefiniowano następujące granice:</p><ul><li><strong>Agregacja Ogłoszeń</strong>: Odpowiedzialny za pobieranie, scrapowanie, walidację danych i zasilanie bazy.</li><li><strong>Zarządzanie Użytkownikiem</strong>: Autoryzacja, zarządzanie profilem i preferencjami.</li><li><strong>Wyszukiwanie i Dopasowywanie</strong>: Algorytm dopasowujący zwierzęta do preferencji, filtrowanie, geolokalizacja.</li><li><strong>Panel Administracyjny</strong>: Weryfikacja ogłoszeń, zarządzanie tagami i schroniskami.</li></ul><h2 id="_4-2-user-stories" tabindex="-1">4.2. User Stories <a class="header-anchor" href="#_4-2-user-stories" aria-label="Permalink to &quot;4.2. User Stories&quot;">​</a></h2><p>Poniżej przedstawiono kluczowe historyjki użytkownika, które stanowią podstawę do tworzenia i priorytetyzacji backlogu projektu ŁapGo.</p><h3 id="kluczowe-historyjki-adopcyjne" tabindex="-1">Kluczowe Historyjki Adopcyjne <a class="header-anchor" href="#kluczowe-historyjki-adopcyjne" aria-label="Permalink to &quot;Kluczowe Historyjki Adopcyjne&quot;">​</a></h3><ul><li>Jako Użytkownik, chcę ustawić szczegółowe preferencje (gatunek, wiek, wielkość, płeć), aby system mógł dopasować ogłoszenia spełniające moje oczekiwania.</li><li>Jako Użytkownik, chcę zobaczyć listę zwierząt dopasowanych do moich preferencji, aby łatwo znaleźć potencjalnego nowego pupila.</li><li>Jako Użytkownik, chcę filtrować i sortować wyniki wyszukiwania (np. po lokalizacji, dacie dodania), aby zawęzić opcje i znaleźć ogłoszenia z najbliższych schronisk.</li><li>Jako Użytkownik, chcę dodać zwierzę do listy ulubionych, aby szybko wrócić do interesujących mnie ogłoszeń i je porównać.</li><li>Jako Użytkownik, chcę wyświetlić dane kontaktowe schroniska na stronie zwierzęcia, aby szybko nawiązać bezpośredni kontakt w sprawie adopcji.</li></ul><h3 id="historyjki-panelu-uzytkownika-i-administracji" tabindex="-1">Historyjki Panelu Użytkownika i Administracji <a class="header-anchor" href="#historyjki-panelu-uzytkownika-i-administracji" aria-label="Permalink to &quot;Historyjki Panelu Użytkownika i Administracji&quot;">​</a></h3><ul><li>Jako Użytkownik, chcę zarejestrować się i zalogować do aplikacji, aby móc zapisywać preferencje i ulubione zwierzęta.</li><li>Jako Schronisko (zweryfikowany użytkownik), chcę dodać własne zwierzęta do adopcji, aby moje ogłoszenia były widoczne w centralnej bazie.</li><li>Jako Administrator, chcę ręcznie weryfikować ogłoszenia z agregatora, aby zapewnić wysoką jakość i aktualność prezentowanych danych.</li><li>Jako Administrator, chcę zmienić status adopcyjny zwierzęcia (np. na &quot;Adoptowany&quot;), aby ogłoszenie przestało być aktywnie wyświetlane użytkownikom.</li></ul><h3 id="historyjki-techniczne-scraping-ai" tabindex="-1">Historyjki Techniczne (Scraping/AI) <a class="header-anchor" href="#historyjki-techniczne-scraping-ai" aria-label="Permalink to &quot;Historyjki Techniczne (Scraping/AI)&quot;">​</a></h3><ul><li>Jako System, chcę używać scrapera opartego na AI (API Gemini) do inteligentnego pobierania i strukturyzowania danych ze stron schronisk.</li><li>Jako System, chcę używać geolokalizacji i map do wyświetlania schronisk na mapie i dopasowywania zwierząt na podstawie odległości.</li></ul>',17)])])}const y=i(t,[["render",r]]);export{d as __pageData,y as default};
